def main():
    pp = os.path.join(D, "podcasts-en.json")
    pods = json.load(open(pp, encoding="utf-8"))
    keep = [p for p in pods["podcasts"] if p["id"] not in {x["id"] for x in PODS}]
    for p in PODS:
        keep.append({**{k: v for k, v in p.items() if k not in ("lines", "vocab")},
                     "lines": [{"s": s, "it": it, "hu": hu} for s, it, hu in p["lines"]],
                     "vocab": [{"it": a, "hu": b} for a, b in p["vocab"]]})
    pods["podcasts"] = keep
    json.dump(pods, open(pp, "w", encoding="utf-8"), ensure_ascii=False, indent=1)
    json.dump({"items": [{"it": s, "why": w} for s, w in ACCENT_TIPS]}, open(os.path.join(D, "accents-en.json"), "w", encoding="utf-8"), ensure_ascii=False, indent=1)
    json.dump({"packs": PACKS}, open(os.path.join(D, "packs-en.json"), "w", encoding="utf-8"), ensure_ascii=False, indent=1)
    json.dump({"reads": READS, "dialogs": DIALOGS}, open(os.path.join(D, "offline-en.json"), "w", encoding="utf-8"), ensure_ascii=False, indent=1)
    n = sum(len(p["items"]) for p in PACKS)
    print(f"podcast: {len(keep)}, akcentus: {len(ACCENT_TIPS)} mondat, csomag: {len(PACKS)} ({n} elem), offline: {len(READS)} olvasmány, {len(DIALOGS)} párbeszéd")


if __name__ == "__main__":
    main()
